COMMENT ON COLUMN analytics.amazon_ads_campaign_daily.clicks IS 'Ad clicks.';
COMMENT ON COLUMN analytics.amazon_ads_campaign_daily.sales_1d IS 'Ad-attributed sales, dollars, 1-day click window. Sponsored Products (v3 report) only; NULL for every other row.';
