COMMENT ON COLUMN analytics.amazon_search_queries_monthly.period_start IS 'First day of the period (Sunday for a week, the 1st for a month).';
COMMENT ON COLUMN analytics.amazon_search_queries_monthly.period_end IS 'Last day of the period.';
